const inp = $input.first().json;

const required = ['file_id', 'chat_id', 'agent_id', 'store_name'];
const missing = required.filter(k => inp[k] === undefined || inp[k] === null || inp[k] === '');
if (missing.length) {
  throw new Error('WF-2: не переданы обязательные поля: ' + missing.join(', '));
}

return [{ json: {
  file_id:       String(inp.file_id),
  chat_id:       inp.chat_id,
  agent_id:      String(inp.agent_id),
  store_name:    String(inp.store_name),
  message_id:    inp.message_id ?? Date.now(),
  source:        inp.source || 'direct',
  store_code:    String(inp.store_code ?? ''),   // №26: код ТТ из маршрута
  route_code:    String(inp.route_code ?? ''),   // 1 маршрут = 1 агент → это и есть его ID у заказчика
} }];

// n8n Code node - определение только графических типов для Telegram + заполнение file_mime по file_path
const items = $input.all();

// Разрешенные графические расширения
const ALLOWED = new Set(["jpg","png","gif","webp","bmp","tiff","heic","heif","svg"]);

// MIME карта по расширениям (включил pdf на всякий случай и несколько часто встречающихся типов)
const extToMime = {
  jpg: "image/jpeg",
  jpeg: "image/jpeg",
  png: "image/png",
  gif: "image/gif",
  webp: "image/webp",
  bmp: "image/bmp",
  tiff: "image/tiff",
  tif: "image/tiff",
  heic: "image/heic",
  heif: "image/heif",
  svg: "image/svg+xml",
  avif: "image/avif",
  pdf: "application/pdf",
  mp4: "video/mp4",
  webm: "video/webm"
};

function normalizeExt(ext) {
  if (!ext) return null;
  ext = String(ext).toLowerCase().replace(/[^a-z0-9]/g, "");
  if (ext === "jpeg") return "jpg";
  if (ext === "tif") return "tiff";
  return ext;
}
function isAllowed(ext) {
  return !!ext && ALLOWED.has(ext);
}
function extFromFilename(name) {
  if (!name || typeof name !== "string") return null;
  const withoutQuery = name.split("?")[0].split("#")[0];
  const lastDot = withoutQuery.lastIndexOf(".");
  if (lastDot === -1) return null;
  return normalizeExt(withoutQuery.slice(lastDot + 1));
}
function extFromMime(mime) {
  if (!mime || typeof mime !== "string") return null;
  mime = mime.toLowerCase();
  const parts = mime.split("/");
  if (parts.length === 2) {
    // image/png -> png ; application/pdf -> pdf
    return normalizeExt(parts[1].split("+")[0]);
  }
  return null;
}
function extFromDataUrl(dataUrl) {
  if (!dataUrl || typeof dataUrl !== "string") return null;
  const m = dataUrl.match(/^data:([^;]+);base64,/i);
  if (!m) return null;
  return extFromMime(m[1]);
}
function extFromUrlOrPath(possibleUrl) {
  if (!possibleUrl) return null;
  try {
    const u = new URL(possibleUrl);
    return extFromFilename(u.pathname);
  } catch (e) {
    return extFromFilename(String(possibleUrl));
  }
}
function getMimeForExt(ext) {
  if (!ext) return null;
  ext = normalizeExt(ext);
  return extToMime[ext] || null;
}

// Собираем строки-кандидаты из разных мест, включая result.*
function collectStringCandidates(j) {
  const c = [];
  const topKeys = ["filename","fileName","file_name","name","originalName","original_filename","title",
                   "file_path","filePath","path","url","fileUrl","file_url","link","href"];
  for (const k of topKeys) if (j[k]) c.push(j[k]);

  const nestedContainers = ["result","document","file","photo","message","payload"];
  for (const key of nestedContainers) {
    const obj = j[key];
    if (!obj || typeof obj !== "object") continue;
    const known = ["file_name","fileName","file_path","filePath","url","path","link","href"];
    for (const k of known) if (obj[k]) c.push(obj[k]);
    for (const subKey of Object.keys(obj)) {
      const val = obj[subKey];
      if (typeof val === "string") c.push(val);
    }
  }
  return c;
}

for (const item of items) {
  const j = item.json || {};
  let detected = null;
  let detectedMime = null;

  // 1) если явно передали file_type и он разрешен
  if (j.file_type && typeof j.file_type === "string") {
    const e = normalizeExt(j.file_type);
    if (isAllowed(e)) detected = e;
  }

  // 2) Попытки по имени/пути, включая result.*
  if (!detected) {
    const candidates = collectStringCandidates(j);
    for (const cand of candidates) {
      const e = extFromFilename(String(cand));
      if (isAllowed(e)) { detected = e; break; }
    }
  }

  // 3) По MIME из входящих полей
  if (!detected) {
    const mimeCandidates = [
      j.mimeType, j.mimetype, j.contentType, j.content_type, j.type,
      j.file && j.file.mime, j.document && (j.document.mime_type || j.document.mimeType || j.document.mimetype),
      j.result && (j.result.mime_type || j.result.mimeType || j.result.mimetype),
      j.message && (j.message.mime_type || j.message.mimetype)
    ];
    for (const m of mimeCandidates) {
      if (!m) continue;
      const e = extFromMime(m);
      if (isAllowed(e)) { detected = e; detectedMime = m; break; }
    }
  }

  // 4) Data URL
  if (!detected) {
    const dataCandidates = [j.data, j.base64, j.content, j.file && j.file.content];
    for (const d of dataCandidates) {
      if (typeof d === "string" && d.startsWith("data:")) {
        const e = extFromDataUrl(d);
        if (isAllowed(e)) { detected = e; break; }
      }
    }
  }

  // 5) URL/path fallback
  if (!detected) {
    const urlCandidates = [
      j.url, j.fileUrl, j.file_url, j.link, j.href,
      j.result && j.result.url, j.result && j.result.file_path, j.result && j.result.fileUrl
    ];
    for (const u of urlCandidates) {
      const e = extFromUrlOrPath(u);
      if (isAllowed(e)) { detected = e; break; }
    }
  }

  // 6) Telegram heuristics
  if (!detected) {
    if (j.message && j.message.photo) detected = "jpg";
    else if (j.message && j.message.sticker) {
      const st = j.message.sticker;
      const fromMime = extFromMime(st.mime_type || st.mimeType || st.mimetype);
      if (isAllowed(fromMime)) detected = fromMime;
      else detected = "webp";
    }
    else if (j.message && j.message.animation) {
      const anim = j.message.animation;
      const fromMime = extFromMime(anim.mime_type || anim.mimeType || anim.mimetype);
      if (isAllowed(fromMime)) detected = fromMime;
      else detected = "gif";
    } else if (j.message && j.message.document) {
      const doc = j.message.document;
      const fromMime = extFromMime(doc.mime_type || doc.mimeType || doc.mimetype);
      if (isAllowed(fromMime)) detected = fromMime;
      else {
        const nameExt = extFromFilename(doc.file_name || doc.fileName || doc.file_name);
        if (isAllowed(nameExt)) detected = nameExt;
      }
    }
  }

  if (!detected) detected = "unknown";

  // --- Заполнение file_mime: приоритеты
  // 1) explicit detectedMime (из mimeCandidates)
  // 2) existing fields в джсоне (j.mimeType / j.mimetype / result.*)
  // 3) вывести mime по расширению, взятому из file_path / result.file_path / других кандидатов
  // 4) null если ничего не вышло

  let finalMime = detectedMime ||
                  j.mimeType || j.mimetype || j.contentType ||
                  (j.result && (j.result.mime_type || j.result.mimetype || j.result.mimeType)) || null;

  if (!finalMime) {
    // попробуем явно взять расширение из file_path и сопоставить
    const pathCandidates = [
      j.file_path, j.filePath, j.path,
      j.result && j.result.file_path, j.result && j.result.filePath,
      j.result && j.result.path
    ];
    let extFromPath = null;
    for (const p of pathCandidates) {
      if (!p) continue;
      const e = extFromFilename(String(p));
      if (e) { extFromPath = e; break; }
    }
    // если не нашли в специальных полях, попробуем остальные строковые кандидаты
    if (!extFromPath) {
      const allStr = collectStringCandidates(j);
      for (const s of allStr) {
        const e = extFromFilename(String(s));
        if (e) { extFromPath = e; break; }
      }
    }
    if (extFromPath) {
      const mimeByExt = getMimeForExt(extFromPath);
      if (mimeByExt) finalMime = mimeByExt;
    }
  }

  item.json.file_type = detected;
  item.json.file_mime = finalMime || null;
}

return items;

// v7.5-format-geo = v7.1-slivers + блок 3b (гео-арбитраж литража крупных ПЭТ).
// v7.1-slivers: парсинг ответа-детекции + ДЕТЕРМИНИРОВАННЫЙ счёт по боксам + ФОРМАТ ТАРЫ (№25)
// + фильтр «щепок» (серия H, 04.08: на документе Flash выдал фантомные боксы шириной 10 и 22
// при медиане полки 31–36 → счёт 67 вместо 65, план Pro-прохода поехал).
// Правило: ИНТЕРЬЕРНЫЙ бокс уже 0.7 медианной ширины своей полки → в диагностику, не в отчёт.
// Боксы у краёв кадра (x_min ≤ 5 или x_max ≥ 995) НЕ отсеиваются — частично видимые единицы
// включаем по промпту (правка п.6 от 27.07).
// Также в _detect добавлен finish_reason — контроль обрезания вывода (MAX_TOKENS/SAFETY).
const raw = $input.first().json;
const cand = raw.candidates?.[0];
const parts = cand?.content?.parts || [];
const textPart = [...parts].reverse().find(p => typeof p.text === 'string');
if (!textPart) {
  throw new Error('Нет текстового ответа Gemini: ' + JSON.stringify(raw).slice(0, 800));
}
const data = JSON.parse(textPart.text);

const BRANDS = ['Буратино', 'AI TEA', 'Chino', 'Компотай', 'Tamga'];
const boxesIn = Array.isArray(data.boxes) ? data.boxes : [];

// 1) валидация координат
const valid = [];
let bad = 0;
for (const b of boxesIn) {
  const c = b && b.box_2d;
  if (!Array.isArray(c) || c.length !== 4 || c.some(v => typeof v !== 'number')) { bad++; continue; }
  const clamped = c.map(v => Math.max(0, Math.min(1000, v)));
  const y0 = clamped[0], x0 = clamped[1], y1 = clamped[2], x1 = clamped[3];
  if (y1 <= y0 || x1 <= x0) { bad++; continue; }
  valid.push(Object.assign({}, b, { box_2d: [y0, x0, y1, x1] }));
}

// 2) дедуп: IoU > 0.7 → остаётся бокс с большей confidence
const iou = (a, b) => {
  const ix = Math.max(0, Math.min(a[3], b[3]) - Math.max(a[1], b[1]));
  const iy = Math.max(0, Math.min(a[2], b[2]) - Math.max(a[0], b[0]));
  const inter = ix * iy;
  const union = (a[3] - a[1]) * (a[2] - a[0]) + (b[3] - b[1]) * (b[2] - b[0]) - inter;
  return union > 0 ? inter / union : 0;
};
valid.sort((a, b) => (b.confidence ?? 0) - (a.confidence ?? 0));
const keptAll = [];
let dups = 0;
for (const b of valid) {
  if (keptAll.some(k => iou(k.box_2d, b.box_2d) > 0.7)) { dups++; continue; }
  keptAll.push(b);
}

// 2b) фильтр «щепок»: аномально узкие интерьерные боксы — артефакты детекции, не товар
const wOf = b => b.box_2d[3] - b.box_2d[1];
const shelfOf = b => Number.isInteger(b.shelf_index) && b.shelf_index > 0 ? b.shelf_index : 0;
const widthsByShelf = new Map();
for (const b of keptAll) {
  const s = shelfOf(b);
  if (!widthsByShelf.has(s)) widthsByShelf.set(s, []);
  widthsByShelf.get(s).push(wOf(b));
}
const medW = new Map();
for (const [s, ws] of widthsByShelf) {
  const sorted = [...ws].sort((a, b) => a - b);
  medW.set(s, sorted[Math.floor(sorted.length / 2)]);
}
const sliversDropped = [];
const kept = keptAll.filter(b => {
  const med = medW.get(shelfOf(b)) || 0;
  const atEdge = b.box_2d[1] <= 5 || b.box_2d[3] >= 995;
  if (!atEdge && med > 0 && wOf(b) < 0.7 * med) { sliversDropped.push(b); return false; }
  return true;
});

// 3) ЧУЖОЙ — в диагностику, не в отчёт
const foreign = kept.filter(b => b.label === 'ЧУЖОЙ');
const ours = kept.filter(b => BRANDS.includes(b.label));

// ── 3b) ФОРМАТ-ГЕО (v7.5, №25-геометрия): арбитраж литража КРУПНЫХ ПЭТ по ширине боксов.
// Калибровка 10.08.2026 на живых боксах Flash (IMG_0643, gt-66): w_rel = ширина бокса ÷ span
// ряда полки; отношение к якорю «банка 0,45 л»: 1 л ≈ 1.18 · 1,5 л ≈ 1.33 · 2 л ≈ 1.54
// (физика диаметров 1.24/1.39/1.58; систематика боксов ≈ −4% сокращается отношением).
// Применяется ТОЛЬКО: плотный полный ряд (гейты density/span), группы ≥3, бренды с крупными ПЭТ,
// есть якорь-банка. 0,5↔1 л НЕ трогаем (шириной не разделяются — калибровка 10.08). Пороги —
// отношениями к якорю, не абсолютами. Диагностика: _detect.format_geo. Ручка: GEO.enabled.
const GEO = { enabled: true, r_1_15: 1.25, r_15_2: 1.43, r_floor: 1.10,
  minGroup: 3, minShelf: 4, densLo: 0.9, densHi: 1.3, spanFrac: 0.8, minAnchor: 3 };
const GEO_ENUM = { 'Буратино': ['ПЭТ 1 л', 'ПЭТ 1,5 л', 'ПЭТ 2 л'], 'Компотай': ['ПЭТ 1 л', 'ПЭТ 1,5 л'] };
const geoDiag = { enabled: GEO.enabled, anchor: null, groups: [] };
if (GEO.enabled) (() => {
  const wOf2 = b => b.box_2d[3] - b.box_2d[1];
  const medOf = xs => { const s = [...xs].sort((a, b) => a - b); return s[Math.floor(s.length / 2)]; };
  const byShelfAll = new Map();
  for (const b of ours) { const s = shelfOf(b); if (!byShelfAll.has(s)) byShelfAll.set(s, []); byShelfAll.get(s).push(b); }
  const meta = new Map();
  let maxSpan = 0;
  for (const [s, arr] of byShelfAll) {
    const span = Math.max(...arr.map(b => b.box_2d[3])) - Math.min(...arr.map(b => b.box_2d[1]));
    const dens = span > 0 ? arr.reduce((a, b) => a + wOf2(b), 0) / span : 0;
    meta.set(s, { span, dens, n: arr.length });
    if (span > maxSpan) maxSpan = span;
  }
  const shelfOk = s => { const m = meta.get(s);
    return !!m && m.n >= GEO.minShelf && m.dens >= GEO.densLo && m.dens <= GEO.densHi && m.span >= GEO.spanFrac * maxSpan; };
  // якорь кадра: медианная относительная ширина банок 0,45 на валидных полках
  const cans = ours.filter(b => b.format === 'банка 0,45 л' && shelfOk(shelfOf(b)));
  if (cans.length < GEO.minAnchor) { geoDiag.anchor = { ok: false, cans: cans.length }; return; }
  const anchor = medOf(cans.map(b => wOf2(b) / meta.get(shelfOf(b)).span));
  geoDiag.anchor = { ok: true, w_rel: +anchor.toFixed(4), cans: cans.length };
  // целевые группы: (полка, бренд, формат) — только крупные ПЭТ и null-ПЭТ брендов из GEO_ENUM
  const tg = new Map();
  for (const b of ours) {
    const allowed = GEO_ENUM[b.label];
    if (!allowed) continue;
    const f = b.format || null;
    if (f !== null && allowed.indexOf(f) === -1) continue;   // банка / 0,5 / 2,4 — не трогаем
    if (!shelfOk(shelfOf(b))) continue;
    const k = shelfOf(b) + '|' + b.label + '|' + (f || 'null');
    if (!tg.has(k)) tg.set(k, []);
    tg.get(k).push(b);
  }
  for (const [k, arr] of tg) {
    const brand = k.split('|')[1];
    if (arr.length < GEO.minGroup) { geoDiag.groups.push({ key: k, n: arr.length, kept: 'мало боксов' }); continue; }
    const r = medOf(arr.map(b => wOf2(b) / meta.get(shelfOf(b)).span)) / anchor;
    if (r < GEO.r_floor) { geoDiag.groups.push({ key: k, n: arr.length, r: +r.toFixed(3), kept: 'зона 0,5/1 л' }); continue; }
    let to = r < GEO.r_1_15 ? 'ПЭТ 1 л' : r < GEO.r_15_2 ? 'ПЭТ 1,5 л' : 'ПЭТ 2 л';
    const allowed = GEO_ENUM[brand];
    if (allowed.indexOf(to) === -1) to = allowed[allowed.length - 1];  // enum-cap бренда (у Компотая нет 2 л)
    const changed = arr.filter(b => (b.format || null) !== to).length;
    arr.forEach(b => { b.format = to; });
    geoDiag.groups.push({ key: k, n: arr.length, r: +r.toFixed(3), to, changed });
  }
})();

// 4) группировка (полка, бренд, подвид, ФОРМАТ) → items; счёт = ЧИСЛО БОКСОВ
const groups = new Map();
for (const b of ours) {
  const shelf = Number.isInteger(b.shelf_index) && b.shelf_index > 0 ? b.shelf_index : 0;
  const fmt = b.format || null;
  const key = shelf + '|' + b.label + '|' + (b.subtype || '') + '|' + (fmt || '');
  if (!groups.has(key)) groups.set(key, { shelf, brand: b.label, subtype: b.subtype || null, format: fmt, boxes: [] });
  groups.get(key).boxes.push(b);
}

const loc = x => x < 333 ? 'слева' : x < 667 ? 'центр' : 'справа';
const items = [...groups.values()].map(g => {
  const centers = g.boxes.map(b => (b.box_2d[1] + b.box_2d[3]) / 2);
  const meanX = centers.reduce((s, v) => s + v, 0) / centers.length;
  return {
    product_name: g.brand,
    product_subtype: g.subtype,
    package_format: g.format,
    shelf_index: g.shelf,
    shelf_location: loc(meanX),
    front_facing_count: g.boxes.length,
    confidence: Math.min.apply(null, g.boxes.map(b => typeof b.confidence === 'number' ? b.confidence : 1)),
    _x: meanX,
  };
}).sort((a, b) => a.shelf_index - b.shelf_index || a._x - b._x);
items.forEach(i => { delete i._x; });

return [{ json: {
  shelves_with_target_product: new Set(items.map(i => i.shelf_index)).size,
  items,
  store_code_on_card: data.store_code_on_card ?? null,
  overall_confidence: typeof data.overall_confidence === 'number' ? data.overall_confidence : null,
  notes: data.notes || '',
  _detect: {                       // диагностика в executions
    boxes_total: boxesIn.length,
    boxes_bad: bad,
    dedup_dropped: dups,
    slivers_dropped: sliversDropped.length,          // серия H: фантомы-щепки
    slivers_raw: sliversDropped,                      // сами щепки — для box_viewer
    foreign_units: foreign.length,
    format_null: ours.filter(b => !b.format).length,
    format_geo: geoDiag,                              // v7.5: арбитраж литража по ширине
    finish_reason: (cand && cand.finishReason) || null, // контроль обрезания вывода
    boxes_raw: kept,
  },
  _usage: {
    prompt_tokens: raw.usageMetadata?.promptTokenCount ?? null,
    cached_tokens: raw.usageMetadata?.cachedContentTokenCount ?? null,
    output_tokens: raw.usageMetadata?.candidatesTokenCount ?? null,
  },
} }];

const response = $input.first().json;
const inp = $('Валидация входа').first().json;

// Время Алматы = UTC+5
const t = new Date(Date.now() + 5 * 3600 * 1000);
const p = x => String(x).padStart(2, '0');
const formattedToday = p(t.getUTCDate()) + '.' + p(t.getUTCMonth() + 1) + '.' + t.getUTCFullYear()
  + ' ' + p(t.getUTCHours()) + ':' + p(t.getUTCMinutes()) + ':' + p(t.getUTCSeconds());

const report_id  = 'R_' + Date.now() + '_' + inp.message_id;  // 1 фото = 1 отчёт
const agent_id   = inp.agent_id;
const store_name = inp.store_name;
const store_code = inp.store_code || '';
const route_code = inp.route_code || '';

const rows = (response.items || [])
  .filter(it => it && it.product_name)
  .map(it => ({
    report_id, formattedToday, store_name, store_code, agent_id, route_code,
    product_name:       it.product_name,
    product_subtype:    it.product_subtype || '',   // null → пустая ячейка
    package_format:     it.package_format || '',    // v7: тара/объём («банка 0,45 л»…), null → пусто
    shelf_index:        it.shelf_index,
    position:           it.shelf_location,
    front_facing_count: it.front_facing_count,
    item_confidence:    it.confidence,          // в таблицу не пишется, оставлено для отладки
    overall_confidence: response.overall_confidence
  }));

return rows.length
  ? rows.map(json => ({ json }))
  : [{ json: { report_id, formattedToday, store_name, store_code, agent_id, route_code,
      product_name: 'ничего не распознано', product_subtype: '', package_format: '',
      notes: response.notes || 'ничего не распознано' } }];

// v8: если проход 2 (Pro) отработал — берём его подвиды, иначе проход 1
let parsed = null;
try { const m = $('Слияние подвидов').first().json; if (m && m.items) parsed = m; } catch (e) {}
if (!parsed) parsed = $('Парсинг обработки Google Vision').first().json;
const inp = $('Валидация входа').first().json;
const prepared = $('Подготовка данных для занесения в таблицу').all();

